head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[style > M > getSize]<br/>Element 의 크기값을 반환합니다.",
    "validation" : [
        "element(필수) 파라미터로 크기를 조회할 대상 Element 를 설정할 수 있어야 합니다.",
        "sizeName(필수) 파라미터를 'height' 로 설정하면 clientHeight 값을 반환해야 합니다.",
        "sizeName(필수) 파라미터를 'width' 로 설정하면 clientWidth 값을 반환해야 합니다.",
        "sizeName(필수) 파라미터를 'innerHeight' 로 설정하면 clientHeight + padding 합산값을 반환해야 합니다.",
        "sizeName(필수) 파라미터를 'innerWidth' 로 설정하면 clientWidth + padding 합산값을 반환해야 합니다.",
        "sizeName(필수) 파라미터를 'outerHeight' 로 설정하면 clientHeight + padding + border 합산값을 반환해야 합니다.",
        "sizeName(필수) 파라미터를 'outerWidth' 로 설정하면 clientWidth + padding + border 합산값을 반환해야 합니다.",
        "sizeName(필수) 파라미터를 'outerMarginHeight' 로 설정하면 clientHeight + padding + border + margin 합산값을 반환해야 합니다.",
        "sizeName(필수) 파라미터를 'outerMarginWidth' 로 설정하면 clientWidth + padding + border + margin 합산값을 반환해야 합니다.",
        "sizeName(필수) 파라미터는 대소문자를 구분하지 않아야 합니다.",
        "element 파라미터가 유효하지 않으면 undefined 를 반환해야 합니다.",
        "sizeName 파라미터가 지원하지 않는 값이면 undefined 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getSize_onclick = function () {
    let sizeName = par_sizeName.getValue();
    let targetEl = document.querySelector("[id*='grp_target']");

    let result = WebSquare.style.getSize(targetEl, sizeName);

    wf_body_bottom.getObj("scwin").setReturnValue("getSize(element, '" + sizeName + "') : " + result);
    wf_body_bottom.getObj("scwin").setReturnValue("typeof : " + typeof result);
}



scwin.btn_getSize_all_onclick = function () {
    let targetEl = document.querySelector("[id*='grp_target']");
    let sizeNames = ["width", "height", "innerWidth", "innerHeight", "outerWidth", "outerHeight", "outerMarginWidth", "outerMarginHeight"];

    for (var i = 0; i < sizeNames.length; i++) {
        var val = WebSquare.style.getSize(targetEl, sizeNames[i]);
        wf_body_bottom.getObj("scwin").setReturnValue(sizeNames[i] + " : " + val);
    }
}



scwin.btn_getSize_invalid_onclick = function () {
    let targetEl = document.querySelector("[id*='grp_target']");

    var r1 = WebSquare.style.getSize(null, "width");
    var r2 = WebSquare.style.getSize(targetEl, "invalidName");

    wf_body_bottom.getObj("scwin").setReturnValue("element=null → " + r1 + " (typeof: " + typeof r1 + ")");
    wf_body_bottom.getObj("scwin").setReturnValue("sizeName='invalidName' → " + r2 + " (typeof: " + typeof r2 + ")");
}
